import reactor.core.publisher.Flux;
import java.time.Duration;

public class BackpressureExample {
    public static void main(String[] args) throws InterruptedException {
        Flux.range(1, 100)
            .log()
            .limitRate(10)
            .subscribe(new org.reactivestreams.Subscriber<Integer>() {
                private org.reactivestreams.Subscription s;

                @Override
                public void onSubscribe(org.reactivestreams.Subscription s) {
                    this.s = s;
                    s.request(5); // Initial demand
                }

                @Override
                public void onNext(Integer integer) {
                    System.out.println("Consumed: " + integer);
                    // Simulate slow processing and request more dynamically
                    try { Thread.sleep(100); } catch (InterruptedException e) {}
                    s.request(1);
                }

                @Override
                public void onError(Throwable t) { t.printStackTrace(); }

                @Override
                public void onComplete() { System.out.println("Done"); }
            });
        Thread.sleep(5000);
    }
}
